import type { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';

export function isJsonSyntaxError(err: unknown): boolean {
  if (typeof err === 'object' && err !== null) {
    const record = err as Record<string, unknown>;
    if (record['type'] === 'entity.parse.failed') {
      return true;
    }
    if (err instanceof SyntaxError && record['status'] === 400) {
      return true;
    }
    if (err instanceof SyntaxError && 'body' in record) {
      return true;
    }
  }
  return false;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction
): void {
  if (res.headersSent) {
    return;
  }

  if (isJsonSyntaxError(err)) {
    res.status(400).json({
      error: 'Invalid JSON payload',
    });
    return;
  }

  if (err instanceof ZodError) {
    res.status(422).json({
      error: 'Validation error',
      details: err.issues,
      errors: err.issues,
    });
    return;
  }

  res.status(500).json({
    error: 'Internal Server Error',
  });
}

