import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService, DuplicateBookmarkError } from './bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('should create a bookmark with id, createdAt, and input properties', () => {
      const input = {
        url: 'https://example.com/guide',
        title: 'Example Guide',
        tags: ['guide', 'test'],
      };

      const bookmark = service.create(input);

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.id.length).toBeGreaterThan(0);
      expect(bookmark.url).toBe(input.url);
      expect(bookmark.title).toBe(input.title);
      expect(bookmark.tags).toEqual(input.tags);
      expect(bookmark.createdAt).toBeDefined();
      expect(Number.isNaN(Date.parse(bookmark.createdAt))).toBe(false);
    });

    it('should create a bookmark without optional fields', () => {
      const input = {
        url: 'https://example.com/minimal',
      };

      const bookmark = service.create(input);

      expect(bookmark.id).toBeDefined();
      expect(bookmark.url).toBe(input.url);
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.tags).toBeUndefined();
    });
  });

  describe('duplicate detection', () => {
    it('should throw DuplicateBookmarkError when creating a bookmark with an existing URL', () => {
      const url = 'https://example.com/duplicate';
      service.create({ url, title: 'First' });

      expect(() => {
        service.create({ url, title: 'Second' });
      }).toThrow(DuplicateBookmarkError);
    });
  });

  describe('retrieval', () => {
    it('should retrieve a bookmark by id', () => {
      const created = service.create({
        url: 'https://example.com/item',
        title: 'Item',
      });

      const retrieved = service.getById(created.id);
      expect(retrieved).toEqual(created);
    });

    it('should return undefined when retrieving a non-existent id', () => {
      const result = service.getById('non-existent-id');
      expect(result).toBeUndefined();
    });

    it('should retrieve all bookmarks sorted by createdAt descending', async () => {
      const first = service.create({ url: 'https://example.com/first' });
      await new Promise<void>((resolve) => setTimeout(resolve, 5));
      const second = service.create({ url: 'https://example.com/second' });

      const all = service.getAll();
      expect(all.length).toBe(2);
      expect(all[0]?.id).toBe(second.id);
      expect(all[1]?.id).toBe(first.id);
    });
  });

  describe('search', () => {
    it('should find bookmarks by title with case-insensitive substring match', () => {
      const b1 = service.create({
        url: 'https://example.com/ts',
        title: 'Mastering TypeScript Today',
      });
      service.create({
        url: 'https://example.com/python',
        title: 'Learn Python Fast',
      });

      const results = service.search('typescript');
      expect(results.length).toBe(1);
      expect(results[0]?.id).toBe(b1.id);

      const upperResults = service.search('SCRIPT');
      expect(upperResults.length).toBe(1);
      expect(upperResults[0]?.id).toBe(b1.id);
    });

    it('should find bookmarks by tags with exact match', () => {
      const b1 = service.create({
        url: 'https://example.com/ts',
        title: 'Title 1',
        tags: ['typescript', 'node'],
      });
      service.create({
        url: 'https://example.com/py',
        title: 'Title 2',
        tags: ['python'],
      });

      const results = service.search('typescript');
      expect(results.length).toBe(1);
      expect(results[0]?.id).toBe(b1.id);

      // Substring of a tag should not match tag exact search
      const partialTagResults = service.search('script');
      expect(partialTagResults.length).toBe(0);
    });

    it('should return empty array when no matches are found', () => {
      service.create({
        url: 'https://example.com/ts',
        title: 'TypeScript Guide',
        tags: ['typescript'],
      });

      const results = service.search('nonexistent');
      expect(results).toEqual([]);
    });

    it('should return empty array for empty or whitespace query', () => {
      service.create({
        url: 'https://example.com/ts',
        title: 'TypeScript Guide',
      });

      expect(service.search('')).toEqual([]);
      expect(service.search('   ')).toEqual([]);
    });
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService, type Bookmark } from '../src/services/bookmark-service.js';

describe('GET /api/v1/bookmarks/search', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  describe('search by title', () => {
    it('should find bookmarks matching title by case-insensitive substring', async () => {
      const b1 = bookmarkService.create({
        url: 'https://example.com/ts',
        title: 'Mastering TypeScript Handbook',
        tags: ['programming'],
      });
      bookmarkService.create({
        url: 'https://example.com/rust',
        title: 'Rust for Beginners',
        tags: ['programming'],
      });

      // Lowercase query against TitleCase title
      const res1 = await request(app)
        .get('/api/v1/bookmarks/search?q=typescript')
        .set('Accept', 'application/json');

      expect(res1.status).toBe(200);
      const list1 = res1.body as Bookmark[];
      expect(Array.isArray(list1)).toBe(true);
      expect(list1.length).toBe(1);
      expect(list1[0]?.id).toBe(b1.id);
      expect(list1[0]?.title).toBe('Mastering TypeScript Handbook');

      // Uppercase substring query
      const res2 = await request(app)
        .get('/api/v1/bookmarks/search?q=BOOK')
        .set('Accept', 'application/json');

      expect(res2.status).toBe(200);
      const list2 = res2.body as Bookmark[];
      expect(list2.length).toBe(1);
      expect(list2[0]?.id).toBe(b1.id);
    });
  });

  describe('search by tag', () => {
    it('should find bookmarks matching a tag by exact match', async () => {
      const b1 = bookmarkService.create({
        url: 'https://example.com/react',
        title: 'Frontend Framework',
        tags: ['react', 'web'],
      });
      const b2 = bookmarkService.create({
        url: 'https://example.com/vue',
        title: 'Alternative Framework',
        tags: ['vue', 'web'],
      });

      // Exact match for 'react' tag
      const res1 = await request(app)
        .get('/api/v1/bookmarks/search?q=react')
        .set('Accept', 'application/json');

      expect(res1.status).toBe(200);
      const list1 = res1.body as Bookmark[];
      expect(list1.length).toBe(1);
      expect(list1[0]?.id).toBe(b1.id);

      // Exact match for shared 'web' tag
      const res2 = await request(app)
        .get('/api/v1/bookmarks/search?q=web')
        .set('Accept', 'application/json');

      expect(res2.status).toBe(200);
      const list2 = res2.body as Bookmark[];
      expect(list2.length).toBe(2);
      const ids = list2.map((item) => item.id);
      expect(ids).toContain(b1.id);
      expect(ids).toContain(b2.id);

      // Substring of a tag should not match when title does not contain it
      const res3 = await request(app)
        .get('/api/v1/bookmarks/search?q=reac')
        .set('Accept', 'application/json');

      expect(res3.status).toBe(200);
      const list3 = res3.body as Bookmark[];
      expect(list3.length).toBe(0);
    });
  });

  describe('no results', () => {
    it('should return empty array and 200 OK when no bookmarks match', async () => {
      bookmarkService.create({
        url: 'https://example.com/database',
        title: 'Database Design',
        tags: ['sql', 'postgres'],
      });

      const response = await request(app)
        .get('/api/v1/bookmarks/search?q=nonexistent-term')
        .set('Accept', 'application/json');

      expect(response.status).toBe(200);
      const body = response.body as Bookmark[];
      expect(Array.isArray(body)).toBe(true);
      expect(body.length).toBe(0);
    });
  });

  describe('empty query validation', () => {
    it('should return 400 when query parameter q is missing', async () => {
      const response = await request(app)
        .get('/api/v1/bookmarks/search')
        .set('Accept', 'application/json');

      expect(response.status).toBe(400);
      const body = response.body as { error: string };
      expect(typeof body.error).toBe('string');
      expect(body.error.length).toBeGreaterThan(0);
    });

    it('should return 400 when query parameter q is empty string', async () => {
      const response = await request(app)
        .get('/api/v1/bookmarks/search?q=')
        .set('Accept', 'application/json');

      expect(response.status).toBe(400);
      const body = response.body as { error: string };
      expect(typeof body.error).toBe('string');
      expect(body.error.length).toBeGreaterThan(0);
    });

    it('should return 400 when query parameter q is whitespace only', async () => {
      const response = await request(app)
        .get('/api/v1/bookmarks/search?q=%20%20%20')
        .set('Accept', 'application/json');

      expect(response.status).toBe(400);
      const body = response.body as { error: string };
      expect(typeof body.error).toBe('string');
      expect(body.error.length).toBeGreaterThan(0);
    });
  });
});

