import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkDTO {
  title?: string;
  tags?: string[];
}

export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: PaginationMeta;
}

export class DuplicateBookmarkError extends Error {
  constructor(message = 'Bookmark with this URL already exists') {
    super(message);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates and stores a new bookmark.
   *
   * @param data - The bookmark data containing the URL, optional title, and optional tags.
   * @returns The newly created bookmark with generated ID and ISO createdAt timestamp.
   * @throws {DuplicateBookmarkError} When a bookmark with the same URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.create({
   *   url: 'https://example.com',
   *   title: 'Example',
   *   tags: ['sample']
   * });
   * console.log(bookmark.id);
   * ```
   */
  create(data: CreateBookmarkDTO): Bookmark {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === data.url) {
        throw new DuplicateBookmarkError(`Bookmark with URL "${data.url}" already exists`);
      }
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: data.url,
      title: data.title,
      tags: data.tags ? [...data.tags] : undefined,
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - The unique UUID string of the bookmark.
   * @returns The matching bookmark, or undefined if no bookmark exists with the given ID.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.getById('123e4567-e89b-12d3-a456-426614174000');
   * if (bookmark) {
   *   console.log(bookmark.title);
   * }
   * ```
   */
  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Retrieves all bookmarks sorted descending by creation timestamp.
   *
   * @returns An array containing all bookmarks, sorted by createdAt descending.
   *
   * @example
   * ```ts
   * const allBookmarks = bookmarkService.getAll();
   * console.log(allBookmarks.length);
   * ```
   */
  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  /**
   * Retrieves a paginated list of bookmarks sorted descending by creation timestamp.
   *
   * @param page - 1-based page number to retrieve.
   * @param limit - Maximum number of bookmarks per page.
   * @returns An object with the paginated bookmarks array and pagination metadata.
   *
   * @example
   * ```ts
   * const { data, pagination } = bookmarkService.getPaginated(1, 20);
   * console.log(`Page ${pagination.page} of ${pagination.totalPages}`);
   * ```
   */
  getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const offset = (page - 1) * limit;
    const data = all.slice(offset, offset + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Partially updates an existing bookmark's title and/or tags.
   *
   * @param id - The UUID of the bookmark to update.
   * @param data - The fields to update (title and/or tags).
   * @returns The updated bookmark object, or undefined if the bookmark was not found.
   *
   * @example
   * ```ts
   * const updated = bookmarkService.update('123e4567-e89b-12d3-a456-426614174000', {
   *   title: 'Updated Title'
   * });
   * ```
   */
  update(id: string, data: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      title: data.title !== undefined ? data.title : existing.title,
      tags: data.tags !== undefined ? [...data.tags] : existing.tags,
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Searches bookmarks by case-insensitive title substring or exact tag match.
   *
   * @param query - The search query term.
   * @returns An array of bookmarks matching either the title or tags, sorted by createdAt descending.
   *
   * @example
   * ```ts
   * const results = bookmarkService.search('typescript');
   * console.log(`Found ${results.length} matches`);
   * ```
   */
  search(query: string): Bookmark[] {
    const trimmed = query.trim();
    if (!trimmed) {
      return [];
    }
    const lower = trimmed.toLowerCase();
    return this.getAll().filter((bookmark) => {
      const titleMatch =
        bookmark.title !== undefined &&
        bookmark.title.toLowerCase().includes(lower);
      const tagMatch =
        bookmark.tags !== undefined &&
        bookmark.tags.some(
          (tag) => tag.toLowerCase() === lower || tag === trimmed
        );
      return titleMatch || tagMatch;
    });
  }

  /**
   * Deletes a bookmark by its unique identifier.
   *
   * @param id - The UUID string of the bookmark to delete.
   * @returns True if the bookmark was found and deleted, false otherwise.
   *
   * @example
   * ```ts
   * const success = bookmarkService.delete('123e4567-e89b-12d3-a456-426614174000');
   * if (success) {
   *   console.log('Bookmark deleted');
   * }
   * ```
   */
  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Removes all bookmarks from memory.
   *
   * @returns Void.
   *
   * @example
   * ```ts
   * bookmarkService.clear();
   * ```
   */
  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService, DuplicateBookmarkError } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const updateBookmarkSchema = z.object({
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type UpdateBookmarkInput = z.infer<typeof updateBookmarkSchema>;

function getQueryString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    return value;
  }
  if (Array.isArray(value) && typeof value[0] === 'string') {
    return value[0];
  }
  return undefined;
}

/**
 * Parses and sanitizes pagination parameters from request query parameters.
 *
 * @param query - The request query dictionary.
 * @returns An object containing normalized page and limit values.
 *
 * @example
 * ```ts
 * const { page, limit } = parsePaginationParams({ page: '2', limit: '50' });
 * console.log(`Page: ${page}, Limit: ${limit}`);
 * ```
 */
export function parsePaginationParams(query: Record<string, unknown>): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  const rawPage = getQueryString(query['page']);
  if (rawPage !== undefined) {
    const parsed = parseInt(rawPage, 10);
    if (!Number.isNaN(parsed)) {
      page = Math.max(1, parsed);
    }
  }

  const rawLimit = getQueryString(query['limit']);
  if (rawLimit !== undefined) {
    const parsed = parseInt(rawLimit, 10);
    if (!Number.isNaN(parsed)) {
      limit = Math.min(100, Math.max(1, parsed));
    }
  }

  return { page, limit };
}

/**
 * Route handler for GET /api/v1/bookmarks.
 * Returns a paginated list of bookmarks sorted by createdAt descending.
 *
 * @param req - Express request object containing optional page and limit query parameters.
 * @param res - Express response object returning HTTP 200 with paginated bookmark results.
 * @returns Void.
 *
 * @example
 * ```http
 * GET /api/v1/bookmarks?page=1&limit=20
 * ```
 */
export function getBookmarksHandler(req: Request, res: Response): void {
  const query = req.query as Record<string, unknown>;
  const { page, limit } = parsePaginationParams(query);
  const paginatedResult = bookmarkService.getPaginated(page, limit);
  res.status(200).json(paginatedResult);
}

/**
 * Route handler for GET /api/v1/bookmarks/search.
 * Searches bookmarks by case-insensitive title substring or exact tag match.
 *
 * @param req - Express request object with required 'q' query parameter.
 * @param res - Express response object returning HTTP 200 with matches, or HTTP 400 on empty query.
 * @returns Void.
 *
 * @example
 * ```http
 * GET /api/v1/bookmarks/search?q=typescript
 * ```
 */
export function searchBookmarksHandler(req: Request, res: Response): void {
  const rawQ = getQueryString(req.query.q);
  if (rawQ === undefined || rawQ.trim() === '') {
    res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
    return;
  }

  const results = bookmarkService.search(rawQ);
  res.status(200).json(results);
}

/**
 * Route handler for GET /api/v1/bookmarks/:id.
 * Retrieves a single bookmark by its UUID.
 *
 * @param req - Express request object with id parameter.
 * @param res - Express response object returning HTTP 200 with bookmark or HTTP 404 if not found.
 * @returns Void.
 *
 * @example
 * ```http
 * GET /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * ```
 */
export function getBookmarkByIdHandler(req: Request, res: Response): void {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const bookmark = bookmarkService.getById(id);

  if (!bookmark) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(200).json(bookmark);
}

/**
 * Route handler for POST /api/v1/bookmarks.
 * Creates a new bookmark with validated URL, title, and tags.
 *
 * @param req - Express request object containing JSON body.
 * @param res - Express response object returning HTTP 201 with created bookmark, or HTTP 409 on duplicate URL.
 * @param next - Express next function for delegating errors.
 * @returns Void.
 *
 * @example
 * ```http
 * POST /api/v1/bookmarks
 * Content-Type: application/json
 *
 * { "url": "https://example.com", "title": "Example" }
 * ```
 */
export function createBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    next(result.error);
    return;
  }

  try {
    const created = bookmarkService.create(result.data);
    res.status(201).json(created);
  } catch (err: unknown) {
    if (err instanceof DuplicateBookmarkError) {
      res.status(409).json({ error: err.message });
      return;
    }
    next(err);
  }
}

/**
 * Route handler for PATCH /api/v1/bookmarks/:id.
 * Partially updates an existing bookmark's title and/or tags. URL changes are rejected.
 *
 * @param req - Express request object with id parameter and optional title/tags body.
 * @param res - Express response object returning HTTP 200 with updated bookmark, HTTP 400 on URL changes, or HTTP 404 if not found.
 * @param next - Express next function for delegating validation errors.
 * @returns Void.
 *
 * @example
 * ```http
 * PATCH /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * Content-Type: application/json
 *
 * { "title": "Updated Title" }
 * ```
 */
export function updateBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const body: unknown = req.body;
  if (typeof body === 'object' && body !== null && 'url' in body && (body as { url: unknown }).url !== undefined) {
    res.status(400).json({ error: 'URL is immutable and cannot be updated' });
    return;
  }

  const result = updateBookmarkSchema.safeParse(body);
  if (!result.success) {
    next(result.error);
    return;
  }

  const updated = bookmarkService.update(id, result.data);
  if (!updated) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(200).json(updated);
}

/**
 * Route handler for DELETE /api/v1/bookmarks/:id.
 * Deletes an existing bookmark by its UUID.
 *
 * @param req - Express request object with id parameter.
 * @param res - Express response object returning HTTP 204 on success or HTTP 404 if not found.
 * @returns Void.
 *
 * @example
 * ```http
 * DELETE /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * ```
 */
export function deleteBookmarkHandler(req: Request, res: Response): void {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(204).send();
}

export const bookmarksRouter = Router();

bookmarksRouter.get(['/', '/api/v1/bookmarks'], getBookmarksHandler);
bookmarksRouter.get(['/search', '/api/v1/bookmarks/search'], searchBookmarksHandler);
bookmarksRouter.get(['/:id', '/api/v1/bookmarks/:id'], getBookmarkByIdHandler);
bookmarksRouter.post(['/', '/api/v1/bookmarks'], createBookmarkHandler);
bookmarksRouter.patch(['/:id', '/api/v1/bookmarks/:id'], updateBookmarkHandler);
bookmarksRouter.delete(['/:id', '/api/v1/bookmarks/:id'], deleteBookmarkHandler);

export default bookmarksRouter;
